class CourierLinux < Formula
  desc "AI coding agent"
  homepage "https://github.com/qzmfranklin/homebrew-tap"
  # Platform choice lives in the argument, not in an on_macos block:
  # brew does not allow `url`/`sha256` inside an on_system block.
  url on_system_conditional(
    linux: on_arch_conditional(
      intel: "https://github.com/qzmfranklin/homebrew-tap/releases/download/courier-linux-0.1.13/Courier-linux-amd64.tar.xz",
    ),
  )
  version "0.1.13"
  sha256 on_system_conditional(
    linux: on_arch_conditional(
      intel: "7d7c18dbc2546ded7690292eb01f8a473141e2082823b30513f2c8b5a76b7e51",
    ),
  )
  license :cannot_represent

  def install
    # The archive is the CEF desktop app's FLAT runtime: the `desktop` binary
    # beside its resource paks and `locales/`. The app resolves its resources
    # exe-relatively, so the whole directory must stay TOGETHER -- copying the
    # binary into bin/ while the paks went elsewhere would install cleanly and then
    # fail to start.
    libexec.install Dir["*"]

    # The rust_binary is named after its package (`desktop`); the command this
    # formula installs is `courier`. A RELATIVE symlink in the keg's bin/ keeps
    # /proc/self/exe inside libexec/, where the paks are, and Homebrew links
    # bin/courier into HOMEBREW_PREFIX/bin like any other formula binary.
    bin.mkpath
    (bin/"courier").make_relative_symlink(libexec/"desktop")
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/courier"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew courier at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed courier is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"courier") unless linked.symlink?
  end


  def caveats
    <<~EOS
      courier-linux installs the CEF desktop app as a single prebuilt tarball and
      runs on ubuntu22 and newer (glibc >= 2.35).

      On hosts with glibc < 2.39 (Ubuntu 22.04 and older), Homebrew adds gcc and
      glibc as implicit dependencies to EVERY formula and builds them from source.
      This formula carries no real dependencies, so install it there with:

        brew install --ignore-dependencies courier-linux

      On glibc >= 2.39 hosts (Ubuntu 24.04+, Homebrew's own supported set), plain
      `brew install courier-linux` works with no extra pulls.

      The command is `courier`; the app keeps its whole runtime beside the binary
      (resource paks and locales) inside the keg's libexec, so do not move the
      binary out of it. On macOS use the cask instead:
      `brew install --cask courier`.
    EOS
  end

  test do
    # The installed app is a CEF desktop app: launching it here would need a
    # display and would test CEF, not this recipe. Assert the SHAPE the formula
    # promises instead -- a `courier` command, the real `desktop` binary it points
    # at, and the flat runtime (resource paks + the locale set) beside that binary,
    # which is what the app resolves exe-relatively at launch.
    assert_predicate bin/"courier", :executable?
    assert_match(%r{desktop$}, File.readlink((bin/"courier").to_s))
    assert_predicate libexec/"desktop", :executable?
    assert_predicate libexec/"resources.pak", :exist?
    assert_operator (libexec/"locales").children.length, :>, 100
  end
